async function handleIncomingPayload(payload,file){
  if(!payload?.kind)return;
  if(payload.kind.startsWith('voice-')||payload.kind==='call-invite'){await handleVoicePayload(payload);return}
  const users=await storeUsers(),me=await ensureIdentity();
  if(payload.kind==='direct-message'){
    const msg=normalizeMessage(payload.message||{});if(!msg.senderAddress||msg.senderAddress===me.address)return;let user=findUserByAddress(users,msg.senderAddress)||{userName:msg.senderUserName,profileDisplayName:msg.senderDisplayName,messaging:{address:msg.senderAddress,ready:true}},conv=await findDirectByAddress(msg.senderAddress);if(!conv)conv=normalizeConversation({id:uid('CHAT'),type:'direct',peerAddress:msg.senderAddress,peerUserName:user.userName||msg.senderUserName,peerDisplayName:displayNameFor(user)||msg.senderDisplayName,messages:[],createdAt:msg.createdAt});if(conv.messages.some(x=>x.id===msg.id))return;conv.peerUserName=user.userName||conv.peerUserName;conv.peerDisplayName=displayNameFor(user)||conv.peerDisplayName;conv.messages.push(msg);conv.updatedAt=msg.createdAt;const viewing=panel?.dataset?.conversationId===conv.id||persistentBubble&&activeConversationId===conv.id;conv.unread=viewing?0:(Number(conv.unread)||0)+1;await persistConversation(conv);await setSetting(LAST_KEY,conv.id);if(!viewing)showTransientBubble(conv,msg);refreshOpenUI(conv.id);updateUnreadBadges();return
  }
  if(payload.kind==='party-invite'){
    const p=payload.party||{};let conv=(await conversations()).find(c=>c.type==='party'&&c.partyId===p.id);if(!conv)conv=normalizeConversation({id:uid('PARTYCHAT'),type:'party',partyId:p.id,partyName:p.name,partyFileId:p.fileId,members:p.members||[],messages:[],createdAt:p.createdAt||iso()});conv.partyName=p.name||conv.partyName;conv.members=p.members||conv.members;conv.partyFileId=p.fileId||conv.partyFileId;const inviter=payload.invitedBy||{},msg=normalizeMessage({id:uid('SYS'),senderAddress:inviter.address||'',senderUserName:inviter.userName||'',senderDisplayName:inviter.displayName||'LotKeys User',text:`Invited you to the Party “${p.name||'LotKeys Party'}”`,system:true,createdAt:iso()});conv.messages.push(msg);conv.unread=(Number(conv.unread)||0)+1;conv.updatedAt=msg.createdAt;await persistConversation(conv);await setSetting(LAST_KEY,conv.id);showTransientBubble(conv,msg);refreshOpenUI(conv.id);updateUnreadBadges();return
  }
  if(payload.kind==='party-message'||payload.kind==='party-system'){
    const msg=normalizeMessage(payload.message||{});let conv=(await conversations()).find(c=>c.type==='party'&&c.partyId===payload.partyId);if(!conv)conv=normalizeConversation({id:uid('PARTYCHAT'),type:'party',partyId:payload.partyId,partyName:payload.partyName||'LotKeys Party',partyFileId:payload.partyFileId||'',members:payload.members||[],messages:[],createdAt:msg.createdAt});if(conv.messages.some(x=>x.id===msg.id))return;conv.partyName=payload.partyName||conv.partyName;conv.partyFileId=payload.partyFileId||conv.partyFileId;conv.members=payload.members||conv.members;conv.messages.push(msg);conv.updatedAt=msg.createdAt;const viewing=panel?.dataset?.conversationId===conv.id||persistentBubble&&activeConversationId===conv.id;conv.unread=viewing?0:(Number(conv.unread)||0)+1;await persistConversation(conv);await setSetting(LAST_KEY,conv.id);if(!viewing)showTransientBubble(conv,msg);refreshOpenUI(conv.id);updateUnreadBadges();return
  }
}
async function loadProcessedRelayIds(){if(processedRelayIds.size)return processedRelayIds;const rows=await setting('lotkeysMessagingProcessedRelayV1',[]);for(const id of Array.isArray(rows)?rows:[])processedRelayIds.add(String(id));return processedRelayIds}
async function markRelayProcessed(id){if(!id)return;processedRelayIds.add(String(id));const rows=[...processedRelayIds].slice(-250);processedRelayIds.clear();for(const x of rows)processedRelayIds.add(x);await setSetting('lotkeysMessagingProcessedRelayV1',rows)}
async function pollInbox(){if(pollBusy)return;pollBusy=true;try{const st=await DriveSync.getStatus();if(!st.connected||!await setting('personalProfileDriveFolderId',''))return;const id=await ensureIdentity(),inbox=await inboxFolder(id.address),files=(await listFiles(`'${qEscape(inbox.id)}' in parents and trashed = false`)).slice(0,RELAY_LIMIT);await loadProcessedRelayIds();for(const file of files){try{if(processedRelayIds.has(String(file.id))){await deleteRelayFile(file);continue}const env=JSON.parse(await fetchText(file.id));if(env.toAddress!==id.address){continue}const payload=await decryptEnvelope(env,id.privateKeyJwk);await handleIncomingPayload(payload,file);await markRelayProcessed(file.id);await deleteRelayFile(file)}catch(err){console.warn('Could not process one incoming LotKeys message',err);if(/decrypt|operation|key/i.test(String(err?.message||err)))await deleteRelayFile(file).catch(()=>{})}}}catch(err){console.warn('Message check deferred',err)}finally{pollBusy=false}}
