async function showConversationMenu(convId){const conv=(await conversations()).find(c=>c.id===convId);if(!conv)return;const sheet=makeSheet(conv.type==='party'?'Party options':'Chat options');const body=sheet.querySelector('.lkmsg-sheet-body');if(conv.type==='party')body.innerHTML=`<button class="lkmsg-option" id="lkmsg-leave-party">🚪 Leave Party &amp; delete my history</button>`;else body.innerHTML=`<button class="lkmsg-option" id="lkmsg-delete-chat">🗑 Delete Chat from my LotKeys</button>`;body.querySelector('#lkmsg-delete-chat')?.addEventListener('click',async()=>{if(!confirm('Delete this chat from your LotKeys Account and personal Google Drive? The other user keeps their copy.'))return;await deleteChat(conv);sheet.remove();openMessagesHome()});body.querySelector('#lkmsg-leave-party')?.addEventListener('click',async()=>{if(!confirm('Leave this Party and permanently delete your copy of its chat history?'))return;await leaveParty(conv);sheet.remove();openMessagesHome()})}
